import{_ as t,o as a,c as s,a0 as n}from"./chunks/framework.ChlVJx0I.js";const u=JSON.parse('{"title":"Safe branch summary extension","description":"","frontmatter":{},"headers":[],"relativePath":"extensions/safe-branch-summary.md","filePath":"extensions/safe-branch-summary.md","lastUpdated":1790160801000}'),i={name:"extensions/safe-branch-summary.md"};function r(o,e,h,d,c,m){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="safe-branch-summary-extension" tabindex="-1">Safe branch summary extension <a class="header-anchor" href="#safe-branch-summary-extension" aria-label="Permalink to &quot;Safe branch summary extension&quot;">​</a></h1><p>Writes the branch summary on <code>/tree</code> navigation in place of pi&#39;s built-in summarizer, budgeting the request so it fits the window the server serves.</p><p>pi budgets the built-in branch summary request at <code>contextWindow - reserveTokens</code>, measured in its own chars/4 estimate. Code-heavy branches tokenize up to about 1.85x denser than that estimate, so a branch that fits the budget still overflows the window the server serves: the request is rejected with <code>exceed_context_size_error</code>, the navigation dies, and no summary is written.</p><h2 id="behavior" tabindex="-1">Behavior <a class="header-anchor" href="#behavior" aria-label="Permalink to &quot;Behavior&quot;">​</a></h2><ul><li>On every summarized <code>/tree</code> navigation, the extension writes the summary itself. The budget for the branch content is the Effective window minus pi&#39;s own <code>branchSummary.reserveTokens</code>, divided by the Inflation factor (default 2.0), so the worst-case tokenization of code content still fits the window.</li><li>The summary request is standalone: the system prompt, the branch prompt, and the preamble are verbatim copies of pi 0.86.1, so the written summary has the same structure as the built-in&#39;s. The output is capped at 4096 tokens, and the usage of the request is recorded on the summary entry.</li><li>The read and modified file sections come from the summarized content, including the file lists carried by nested branch summaries.</li><li>When the summary cannot be written (the window is at or below the reserve margin, the request fails, the response is not usable, or the branch has nothing that fits), the navigation degrades to a Soft-skip: it completes without a branch summary entry, with a notice. The abandoned branch stays reachable through <code>/tree</code>.</li><li>A user abort cancels the navigation, the same as the built-in.</li><li>With the extension disabled in settings, pi&#39;s built-in summarizer runs instead, unchanged.</li></ul><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Both keys go in <code>settings.json</code> (project overrides global, per pi&#39;s usual merge):</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>safeBranchSummary.enabled</code></td><td><code>true</code></td><td><code>false</code> hands summarized navigation back to pi&#39;s built-in summarizer.</td></tr><tr><td><code>safeBranchSummary.inflationFactor</code></td><td><code>2.0</code></td><td>The Inflation factor: how many estimated tokens one real token is budgeted for. Raise it for denser content (CJK, heavy symbol names); lower it to keep more branch content per summary.</td></tr></tbody></table><p>The reserve margin is pi&#39;s own <code>branchSummary.reserveTokens</code> (default 16384); the extension reads it from the same settings and does not add a second margin.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>The decision logic lives in the engine-free core module (<code>extensions/safe-branch-summary/core.ts</code>): the budget math, the selection of the branch content, and the prompt assembly. The pi wiring (<code>index.ts</code>) registers one handler on the before-tree event and supplies the real dependencies (settings, the session&#39;s model, the model registry completion). The prompts (<code>prompts.ts</code>) are verbatim copies of pi 0.86.1, pinned by their source version. See <a href="/pi-extensions/adr/0025-safe-branch-summary-replaces-the-built-in.html">ADR 0025</a>.</p><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><p>Content denser than 2 chars per token (for example CJK) is not covered by the default factor 2.0 and can still overflow the window; the Soft-skip then degrades the navigation to summary-less instead of failing it. If pi changes its branch summary prompts, the copies drift silently: the format stays model-readable, and the extension keeps working.</p>',13)])])}const b=t(i,[["render",r]]);export{u as __pageData,b as default};
